std::string uuid(unsigned n){char s[64];std::snprintf(s,sizeof(s),"B0000000-0000-4000-8000-%012u",n);return s;}
mod::ReaderBook book(unsigned n){return mod::windowsReaderReference(uuid(n),"C:\\Owned-unopened-reader-fixture\\book"+std::to_string(n)+".txt","Synthetic book "+std::to_string(n));}
struct Repository:mod::ReaderRepository {mod::ReaderLibrary saved;unsigned reads{},writes{};mod::ReaderLibrary load()override{++reads;return saved;}void save(const mod::ReaderLibrary&next)override{++writes;saved=next;}};
struct Queue {struct Job{std::function<void()>work;std::function<void(std::exception_ptr)>done;};std::deque<Job>jobs;mod::ReaderExecutor executor(){return {[this](auto work,auto done){if(jobs.size()>=32)return false;jobs.push_back({std::move(work),std::move(done)});return true;}};}void drain(){for(unsigned n=0;!jobs.empty();++n){check(n<100,"Injected FIFO does not spin or install a retry timer");auto job=std::move(jobs.front());jobs.pop_front();std::exception_ptr error;try{job.work();}catch(...){error=std::current_exception();}job.done(error);}}};
struct Source:mod::ReaderDocumentSource {
    unsigned opens{},renders{},details{},releases{};bool illustration{};std::shared_ptr<const mod::ReaderPagePixels>detailPixels;std::string opened;std::array<std::shared_ptr<const mod::ReaderPagePixels>,3>pixels;
    Source(){for(unsigned k=0;k<3;++k){auto p=std::make_shared<mod::ReaderPagePixels>();p->width=p->height=200;p->format=mod::ReaderPagePixels::Format::bgra8Premultiplied;for(unsigned n=0;n<200*200;++n)p->bytes.insert(p->bytes.end(),{0,static_cast<std::uint8_t>(k==1?255:0),static_cast<std::uint8_t>(k==0?255:0),255});pixels[k]=p;}auto crop=std::make_shared<mod::ReaderPagePixels>();crop->width=crop->height=200;crop->format=mod::ReaderPagePixels::Format::bgra8Premultiplied;for(unsigned n=0;n<200*200;++n)crop->bytes.insert(crop->bytes.end(),{255,0,0,255});detailPixels=crop;}
    void open(const mod::ReaderBook&b,const std::function<bool()>&cancel)override{if(!cancel()){++opens;opened=b.id;}}
    mod::ReaderPage page(int n){mod::ReaderPage p;p.location.section=n;p.progress=n/2.;p.summary="Injected page";p.illustration=illustration;p.pixels=pixels[static_cast<std::size_t>(n)];if(n<2)p.next=mod::ReaderLocation{n+1};if(n>0)p.previous=mod::ReaderLocation{n-1};return p;}
    std::vector<mod::ReaderPage>render(std::optional<mod::ReaderLocation>where,std::optional<double>progress,const mod::ReaderPreferences&,core::Point,bool,const std::function<bool()>&cancel)override{if(cancel())return {};check(!opened.empty(),"Only injected provider's retained synthetic document renders");++renders;const auto n=progress?static_cast<int>(*progress*2):static_cast<int>(where.value_or(mod::ReaderLocation{}).section);auto current=page(std::clamp(n,0,2));std::vector<mod::ReaderPage>p{current};if(current.next)p.push_back(page(static_cast<int>(current.next->section)));if(current.previous)p.push_back(page(static_cast<int>(current.previous->section)));return p;}
    mod::ReaderPage detail(mod::ReaderLocation l,const mod::ReaderPreferences&,core::Point,bool,mod::ReaderImageView,const std::function<bool()>&cancel)override{if(cancel())return {};++details;auto result=page(static_cast<int>(l.section));if(illustration)result.pixels=detailPixels;return result;}
    void release()override{++releases;opened.clear();}
};
