    const auto point=[&](double x,double y){auto p=plane.project({x,y});check(bool(p),"Existing shared source projection maps Reader fixture input");return *p;};
    const auto click=[&](double x,double y){const auto p=point(x,y);check(preview.pointer({app::PointerKind::down,app::PointerButton::left,p.x,p.y},time+=.2),"Source Reader action receives projected pointer down");preview.pointer({app::PointerKind::up,app::PointerButton::left,p.x,p.y},time+=.01);};
