    const auto scrollPoint=point(200,200);const auto renders=provider->renders;check(preview.wheel({scrollPoint.x,scrollPoint.y,-1,false,0,3},time+=.2),"Inner Reader wheel consumes original viewport input");frame(time+.2);check(provider->renders==renders,"Small text scroll repositions bounded cached page pixels without decode work");
    click(100,20);check(preview.pointerLocked(),"Original Library menu retains local input routing");mod::ReaderMenuInput library;library.type=mod::ReaderMenuType::library;for(const auto&b:state.library().books)library.choices.push_back({b.id,b.title});const auto sourceLibrary=mod::prepareReaderMenu(library);const auto closeAction=std::find_if(sourceLibrary.actions.begin(),sourceLibrary.actions.end(),[](const auto&a){return a.id=="close";});check(closeAction!=sourceLibrary.actions.end(),"Original list has its close action");click(42+closeAction->rect.x+10,44+closeAction->rect.y+10);frame(time+.3);check(!preview.pointerLocked(),"Closing Library relinquishes menu input after its finite fade");
