    frame(time+.2);provider->illustration=true;state.setLayout({376,334},false);queue.drain();frame(time+.2);click(234,400);check(preview.nextWakeTime().has_value(),"Actual zoom button schedules the one shared detail deadline");preview.deadline(time+=.13);queue.drain();frame(time+.01);const auto sampleBlue=[&]{const auto p=point(200,200);const auto image=renderer.readback();const auto offset=static_cast<std::size_t>(p.y)*image.rowBytes+static_cast<std::size_t>(p.x)*4;return std::array{image.pixels[offset],image.pixels[offset+1],image.pixels[offset+2]};};check(sampleBlue()[0]>250&&sampleBlue()[2]<5,"Actual button detail completion publishes the synthetic cropped image");const auto buttonUploads=renderer.stats().textureUploads;const auto buttonRasters=raster.stats();const auto buttonDetails=provider->details;click(234,400);frame(time+.01);check(sampleBlue()[2]>250&&provider->details==buttonDetails&&renderer.stats().textureUploads==buttonUploads&&raster.stats().rasterizations==buttonRasters.rasterizations&&raster.stats().textLayoutsCreated==buttonRasters.textLayoutsCreated,"Plus button changes zoom immediately before any new detail completion without reuploading full pixels or rebuilding controls");preview.deadline(time+=.13);queue.drain();frame(time+.01);check(sampleBlue()[0]>250,"Latest higher zoom accepts only its tagged detail");click(165,400);frame(time+.01);check(sampleBlue()[2]>250,"Minus button also discards an obsolete crop immediately");preview.deadline(time+=.13);queue.drain();frame(time+.01);check(sampleBlue()[0]>250,"Lower zoom can install its own current detail");click(200,400);frame(time+.01);check(sampleBlue()[2]>250&&!preview.nextWakeTime(),"Reset button immediately restores the full page and clears detail scheduling");
